<?php
if (!defined('ABSPATH')) exit;
/** DARES Piketrooster 2.0: additive schema and opt-in functionality. */
final class Dares_Piket_V2 {
 const OPT='dares_piket_v2_settings';
 static function table($name){global $wpdb; return $wpdb->prefix.'dares_piket_v2_'.$name;}
 static function init(){
  add_action('init',[__CLASS__,'upgrade']);add_action('admin_menu',[__CLASS__,'menu']);
  add_action('admin_post_dares_piket_v2',[__CLASS__,'action']);
  add_action('admin_post_nopriv_dares_piket_v2_feed',[__CLASS__,'feed']);add_action('admin_post_dares_piket_v2_feed',[__CLASS__,'feed']);
  add_action('dares_piket_tick',[__CLASS__,'audit']);
  add_shortcode('dares_piket_dashboard',[__CLASS__,'dashboard']);add_shortcode('dares_piket_jaarplanner',[__CLASS__,'year']);
  add_shortcode('dares_piket_mijn_profiel',[__CLASS__,'profile']);add_shortcode('dares_piket_ruilen',[__CLASS__,'swaps']);
  add_action('wp_enqueue_scripts',[__CLASS__,'assets']);add_action('wp_head',[__CLASS__,'pwa_head']);
  add_action('template_redirect',[__CLASS__,'pwa_route']);
 }
 static function upgrade(){if(get_option('dares_piket_v2_schema')==='2.0.0')return; global $wpdb;require_once ABSPATH.'wp-admin/includes/upgrade.php';$c=$wpdb->get_charset_collate();
  dbDelta('CREATE TABLE '.self::table('feeds').' (person_id bigint(20) unsigned NOT NULL, token_hash char(64) NOT NULL, created_at datetime NOT NULL, PRIMARY KEY (person_id), UNIQUE KEY token_hash (token_hash)) '.$c.';');
  dbDelta('CREATE TABLE '.self::table('swaps').' (id bigint(20) unsigned NOT NULL AUTO_INCREMENT, shift_id bigint(20) unsigned NOT NULL, requested_by bigint(20) unsigned NOT NULL, requested_to bigint(20) unsigned NOT NULL, state varchar(20) NOT NULL DEFAULT "pending", created_at datetime NOT NULL, decided_at datetime NULL, PRIMARY KEY (id), KEY shift_id (shift_id), KEY requested_to (requested_to)) '.$c.';');
  dbDelta('CREATE TABLE '.self::table('cancelled').' (shift_id bigint(20) unsigned NOT NULL, person_id bigint(20) unsigned NOT NULL, canceled_at datetime NOT NULL, PRIMARY KEY (shift_id,person_id), KEY person_id (person_id)) '.$c.';');
  dbDelta('CREATE TABLE '.self::table('events').' (id bigint(20) unsigned NOT NULL AUTO_INCREMENT, code varchar(70) NOT NULL, event_key varchar(191) NOT NULL, details text NULL, created_at datetime NOT NULL, PRIMARY KEY (id), UNIQUE KEY event_key (event_key)) '.$c.';');
  self::sync_snapshot(true);update_option('dares_piket_v2_schema','2.0.0',false);
 }
 static function settings(){return wp_parse_args((array)get_option(self::OPT,[]),['deadline_hours'=>48,'escalate_email'=>'','alarm_alert'=>0,'pwa'=>0,'pwa_button'=>1]);}
 static function menu(){add_submenu_page('dares-piketrooster','Piketbeheer 2.0','Piketbeheer 2.0','manage_options','dares-piket-v2',[__CLASS__,'admin']);}
 static function nonce_form($kind){echo '<input type="hidden" name="action" value="dares_piket_v2"><input type="hidden" name="kind" value="'.esc_attr($kind).'">';wp_nonce_field('dares_piket_v2_'.$kind);}
 static function admin(){if(!current_user_can('manage_options'))wp_die('Geen toegang');global $wpdb;$o=self::settings();$people=Dares_Piketrooster::people();$now=Dares_Piketrooster::now();$t=Dares_Piketrooster::tables();$up=$wpdb->get_results($wpdb->prepare("SELECT s.*,p.name person_name,g.name group_name FROM {$t['shifts']} s JOIN {$t['people']} p ON s.person_id=p.id JOIN {$t['groups']} g ON g.id=s.group_id WHERE s.end_at>%s ORDER BY s.start_at LIMIT 200",$now));$conf=self::conflicts();
  echo '<div class="wrap dares-v2"><h1>DARES · Piketbeheer 2.0</h1><p>Het bestaande rooster blijft leidend. Automatische diensten wisselen maandag om 18:00.</p>';
  echo '<div class="dares-v2-stats"><div><b>'.count($up).'</b><span>Komende / lopende diensten</span></div><div><b>'.count($conf).'</b><span>Roosterwaarschuwingen</span></div><div><b>'.count($people).'</b><span>Medewerkers</span></div></div>';
  echo '<h2>Controle en waarschuwingen</h2><div class="dares-v2-box">';if(!$conf)echo '<p>Geen overlappende diensten, afwezigheidsconflicten of afwijkende automatische wisseltijden gevonden.</p>';foreach($conf as $c)echo '<p>⚠️ '.esc_html($c).'</p>';echo '</div>';
  echo '<h2>Herinneringen en escalatie</h2><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';self::nonce_form('settings');echo '<p>Uren vóór aanvang voor bevestigingsdeadline: <input type="number" min="1" max="168" name="deadline_hours" value="'.esc_attr($o['deadline_hours']).'"></p><p>Escalatieadres (coördinator): <input type="email" name="escalate_email" class="regular-text" value="'.esc_attr($o['escalate_email']).'"></p><p><label><input type="checkbox" name="alarm_alert" value="1" '.checked($o['alarm_alert'],1,false).'> Extra waarschuwingen op alarmstatus via bestaande koppeling</label></p><p><label><input type="checkbox" name="pwa" value="1" '.checked($o['pwa'],1,false).'> PWA-manifest beschikbaar maken</label></p><p><label><input type="checkbox" name="pwa_button" value="1" '.checked($o['pwa_button'],1,false).'> Knop Open DARES Piket-app tonen op piketpagina en widget</label></p><button class="button button-primary">Bewaren</button></form>';
  if(class_exists('Dares_Piket_PWA'))Dares_Piket_PWA::admin_fields();
  echo '<h2>Persoonlijke agenda-abonnementen</h2><p>Maak voor een medewerker een privélink aan. De link is alleen zichtbaar bij aanmaken, bewaar hem veilig. Bij verlies kun je hem intrekken en vernieuwen.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';self::nonce_form('new_feed');echo '<select name="person_id">';foreach($people as $p)echo '<option value="'.esc_attr($p->id).'">'.esc_html($p->name).'</option>';echo '</select> <button class="button">Nieuwe privé-agendalink maken</button></form>';
  if(isset($_GET['feed_token'])&&get_transient('dares_piket_feed_result_'.get_current_user_id())){$url=get_transient('dares_piket_feed_result_'.get_current_user_id());delete_transient('dares_piket_feed_result_'.get_current_user_id());echo '<div class="notice notice-success"><p><strong>Bewaar deze persoonlijke kalender-URL:</strong></p><input class="large-text" readonly onclick="this.select()" value="'.esc_attr($url).'"></div>';}
  echo '<h2>Piketdiensten ruilen</h2><p>Medewerkers kunnen via <code>[dares_piket_ruilen]</code> een ruil aanvragen. De ontvangende medewerker accepteert en een beheerder keurt de ruil definitief goed.</p>';
  $requests=$wpdb->get_results('SELECT * FROM '.self::table('swaps').' ORDER BY id DESC LIMIT 50');echo '<table class="widefat striped"><thead><tr><th>Dienst</th><th>Van</th><th>Naar</th><th>Status</th><th>Actie</th></tr></thead><tbody>';foreach($requests as $r){echo '<tr><td>#'.(int)$r->shift_id.'</td><td>#'.(int)$r->requested_by.'</td><td>#'.(int)$r->requested_to.'</td><td>'.esc_html($r->state).'</td><td>';if($r->state==='accepted'){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';self::nonce_form('approve_swap');echo '<input type="hidden" name="swap_id" value="'.(int)$r->id.'"><button class="button">Ruil goedkeuren</button></form>';}echo '</td></tr>';}echo '</tbody></table>';
  echo '<h2>Jaarplanner en PDF</h2><p><code>[dares_piket_jaarplanner]</code> toont de jaarplanning. Open de afdrukweergave om via de browser als PDF op te slaan.</p><p><a class="button" target="_blank" rel="noopener" href="'.esc_url(add_query_arg('dares_piket_print','1',home_url('/'))).'">Rooster printen / bewaren als PDF</a></p>';
  echo '<h2>Logboek</h2>';foreach($wpdb->get_results('SELECT * FROM '.self::table('events').' ORDER BY id DESC LIMIT 50') as $e)echo '<p>'.esc_html($e->created_at.' · '.$e->code.' · '.$e->details).'</p>';echo '</div>';
 }
 static function log($code,$key,$details){global $wpdb;$wpdb->query($wpdb->prepare('INSERT IGNORE INTO '.self::table('events').' (code,event_key,details,created_at) VALUES (%s,%s,%s,%s)',$code,substr($key,0,191),$details,Dares_Piketrooster::now()));}
 static function action(){if(!is_user_logged_in())wp_die('Log in');$kind=sanitize_key($_POST['kind']??'');check_admin_referer('dares_piket_v2_'.$kind);global $wpdb;
  if($kind==='settings'){if(!current_user_can('manage_options'))wp_die('Geen toegang');update_option(self::OPT,['deadline_hours'=>min(168,max(1,absint($_POST['deadline_hours']??48))),'escalate_email'=>sanitize_email($_POST['escalate_email']??''),'alarm_alert'=>empty($_POST['alarm_alert'])?0:1,'pwa'=>empty($_POST['pwa'])?0:1,'pwa_button'=>empty($_POST['pwa_button'])?0:1],false);self::back();}
  if($kind==='new_feed'){if(!current_user_can('manage_options'))wp_die('Geen toegang');$id=absint($_POST['person_id']??0);$people=Dares_Piketrooster::people();$ids=array_map(static function($p){return (int)$p->id;},$people);if(!in_array($id,$ids,true))wp_die('Ongeldige medewerker');$token=bin2hex(random_bytes(32));$wpdb->replace(self::table('feeds'),['person_id'=>$id,'token_hash'=>hash('sha256',$token),'created_at'=>Dares_Piketrooster::now()]);$url=add_query_arg(['action'=>'dares_piket_v2_feed','pid'=>$id,'key'=>$token],admin_url('admin-post.php'));set_transient('dares_piket_feed_result_'.get_current_user_id(),$url,120);wp_safe_redirect(add_query_arg(['page'=>'dares-piket-v2','feed_token'=>1],admin_url('admin.php')));exit;}
  if($kind==='request_swap'){$sid=absint($_POST['shift_id']??0);$target=absint($_POST['person_id']??0);$shift=self::shift($sid);if(!$shift||!Dares_Piket_Advanced::owns($shift->person_id,get_current_user_id())||$shift->person_id==$target)wp_die('Geen toegang');$p=self::person($target);if(!$p||!$p->active||Dares_Piket_Advanced::absent($target,$shift->start_at,$shift->end_at))wp_die('Medewerker niet beschikbaar');$wpdb->insert(self::table('swaps'),['shift_id'=>$sid,'requested_by'=>$shift->person_id,'requested_to'=>$target,'state'=>'pending','created_at'=>Dares_Piketrooster::now()]);self::log('swap-request','swap-request-'.$wpdb->insert_id,'Ruilverzoek voor dienst '.$sid);if($p->email)wp_mail($p->email,'DARES: piketruil aangevraagd','Er is een piketruil aangevraagd. Log in op het piketportaal om te reageren: '.Dares_Piket_Advanced::portal_url());self::back();}
  if($kind==='accept_swap'){$id=absint($_POST['swap_id']??0);$r=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.self::table('swaps').' WHERE id=%d',$id));if(!$r||$r->state!=='pending'||!Dares_Piket_Advanced::owns($r->requested_to,get_current_user_id()))wp_die('Geen toegang');$wpdb->update(self::table('swaps'),['state'=>'accepted','decided_at'=>Dares_Piketrooster::now()],['id'=>$id]);self::log('swap-accepted','swap-accepted-'.$id,'Ruil geaccepteerd, wacht op beheerder');$to=self::settings()['escalate_email']?:get_option('admin_email');if($to)wp_mail($to,'DARES: piketruil wacht op goedkeuring','Controleer het ruilverzoek in Piketbeheer 2.0.');self::back();}
  if($kind==='approve_swap'){if(!current_user_can('manage_options'))wp_die('Geen toegang');$id=absint($_POST['swap_id']??0);$r=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.self::table('swaps').' WHERE id=%d',$id));$s=$r?self::shift($r->shift_id):null;$p=$r?self::person($r->requested_to):null;if(!$r||$r->state!=='accepted'||!$s||!$p||$s->person_id!=$r->requested_by||Dares_Piket_Advanced::absent($p->id,$s->start_at,$s->end_at))wp_die('Ruil niet meer geldig');$before=clone $s;$wpdb->update(Dares_Piket_Advanced::t('shifts'),['person_id'=>$p->id,'group_id'=>$p->group_id],['id'=>$s->id]);$wpdb->delete(Dares_Piket_Advanced::t('confirm'),['shift_id'=>$s->id]);$wpdb->update(self::table('swaps'),['state'=>'approved','decided_at'=>Dares_Piketrooster::now()],['id'=>$id]);self::log('swap-approved','swap-approved-'.$id,'Dienst '.$s->id.' toegewezen aan '.$p->name);if(class_exists('Dares_Piket_Rooster_Mail'))Dares_Piket_Rooster_Mail::changed($before,self::shift($s->id));self::back();}
  wp_die('Onbekende actie');
 }
 static function back(){wp_safe_redirect(wp_get_referer()?:admin_url('admin.php?page=dares-piket-v2'));exit;}
 static function shift($id){global $wpdb;return $wpdb->get_row($wpdb->prepare('SELECT * FROM '.Dares_Piket_Advanced::t('shifts').' WHERE id=%d',$id));}
 static function person($id){global $wpdb;return $wpdb->get_row($wpdb->prepare('SELECT * FROM '.Dares_Piket_Advanced::t('people').' WHERE id=%d',$id));}
 static function mine(){global $wpdb;return $wpdb->get_results($wpdb->prepare('SELECT p.* FROM '.Dares_Piket_Advanced::t('people').' p JOIN '.Dares_Piket_Advanced::t('meta').' m ON p.id=m.person_id WHERE m.user_id=%d',get_current_user_id()));}
 static function swaps(){if(!is_user_logged_in())return '<p>Log in om diensten te ruilen.</p>';global $wpdb;$mine=self::mine();if(!$mine)return '<p>Koppel je account eerst aan een medewerker.</p>';$ids=array_map(static function($p){return (int)$p->id;},$mine);$now=Dares_Piketrooster::now();$shifts=$wpdb->get_results($wpdb->prepare('SELECT * FROM '.Dares_Piket_Advanced::t('shifts').' WHERE end_at>%s ORDER BY start_at LIMIT 200',$now));ob_start();echo '<div class="dares-v2-box"><h3>Ruil een piketdienst</h3>';foreach($shifts as $s)if(in_array((int)$s->person_id,$ids,true)){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';self::nonce_form('request_swap');echo '<input type="hidden" name="shift_id" value="'.(int)$s->id.'"><label>'.esc_html($s->start_at).' – '.esc_html($s->end_at).' <select name="person_id">';foreach(Dares_Piketrooster::people() as $p)if($p->active&&!in_array((int)$p->id,$ids,true))echo '<option value="'.(int)$p->id.'">'.esc_html($p->name).'</option>';echo '</select></label> <button>Ruil aanvragen</button></form>';}
  $requests=$wpdb->get_results('SELECT * FROM '.self::table('swaps').' WHERE state="pending" ORDER BY id DESC LIMIT 100');foreach($requests as $r)if(in_array((int)$r->requested_to,$ids,true)){echo '<p>Ruilverzoek voor dienst #'.(int)$r->shift_id.'</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';self::nonce_form('accept_swap');echo '<input type="hidden" name="swap_id" value="'.(int)$r->id.'"><button>Accepteren (beheerder beslist)</button></form>';}echo '</div>';return ob_get_clean();
 }
 static function profile(){if(!is_user_logged_in())return '<p>Log in om je profiel te bekijken.</p>';$mine=self::mine();if(!$mine)return '<p>Geen medewerker aan dit account gekoppeld.</p>';$out='<div class="dares-v2-box"><h3>Mijn DARES-profiel</h3>';foreach($mine as $p)$out.='<p><strong>'.esc_html($p->name).'</strong> · '.esc_html($p->email).' · '.esc_html($p->phone).'</p>';return $out.'<p>Contactgegevens worden door een beheerder bijgewerkt, zodat ze gecontroleerd blijven.</p></div>';}
 static function conflicts(){global $wpdb;$rows=$wpdb->get_results($wpdb->prepare('SELECT s.*,p.name FROM '.Dares_Piket_Advanced::t('shifts').' s LEFT JOIN '.Dares_Piket_Advanced::t('people').' p ON p.id=s.person_id WHERE s.end_at>%s ORDER BY start_at LIMIT 1000',Dares_Piketrooster::now()));$problems=[];$last=null;foreach($rows as $s){if($last&&$s->start_at<$last->end_at)$problems[]='Overlapping: diensten #'.$last->id.' en #'.$s->id;if($last&&$s->start_at>$last->end_at)$problems[]='Onbezet interval tussen '.$last->end_at.' en '.$s->start_at;if(Dares_Piket_Advanced::absent($s->person_id,$s->start_at,$s->end_at))$problems[]='Afwezigheidsconflict: '.$s->name.' (dienst #'.$s->id.')';$d=new DateTimeImmutable($s->start_at,wp_timezone());if($d->format('N H:i')!=='1 18:00')$problems[]='Afwijkende starttijd dienst #'.$s->id.' (handmatige overname kan toegestaan zijn)';if(!$last||$s->end_at>$last->end_at)$last=$s;if(count($problems)>150)break;}return $problems;}
 static function dashboard(){if(!is_user_logged_in())return '<p>Log in om het beheerdashboard te zien.</p>';$current=Dares_Piketrooster::global_current();$problems=current_user_can('manage_options')?self::conflicts():[];$out='<div class="dares-v2-box"><h2>DARES Piketdashboard</h2><p><b>Nu piket:</b> '.($current?esc_html($current->name.' · '.$current->group_name):'Geen actieve dienst').'</p><p><b>Controlewaarschuwingen:</b> '.count($problems).'</p><p><a href="'.esc_url(Dares_Piket_Advanced::portal_url()).'">Mijn piketportaal</a></p></div>';return $out;}
 static function year($a=[]){$a=shortcode_atts(['jaar'=>wp_date('Y')],$a);$year=min(2100,max(2020,absint($_GET['piket_jaar']??$a['jaar'])));global $wpdb;$from=$year.'-01-01 00:00:00';$to=($year+1).'-01-01 00:00:00';$rows=$wpdb->get_results($wpdb->prepare('SELECT s.*,p.name,g.name group_name FROM '.Dares_Piket_Advanced::t('shifts').' s JOIN '.Dares_Piket_Advanced::t('people').' p ON p.id=s.person_id JOIN '.Dares_Piket_Advanced::t('groups').' g ON g.id=s.group_id WHERE s.start_at<%s AND s.end_at>%s ORDER BY s.start_at LIMIT 1000',$to,$from));$prev=add_query_arg('piket_jaar',$year-1);$next=add_query_arg('piket_jaar',$year+1);$out='<div class="dares-v2-box"><h3>Jaarplanner '.$year.'</h3><p><a href="'.esc_url($prev).'">← Vorig jaar</a> &nbsp; <a href="'.esc_url($next).'">Volgend jaar →</a></p><div class="dares-v2-year">';foreach($rows as $r)$out.='<div><b>'.esc_html($r->name).'</b><small>'.esc_html($r->group_name).'</small><span>'.esc_html((new DateTimeImmutable($r->start_at,wp_timezone()))->format('d-m')).' – '.esc_html((new DateTimeImmutable($r->end_at,wp_timezone()))->format('d-m')).'</span></div>';return $out.'</div></div>';}
 static function feed(){global $wpdb;$pid=absint($_GET['pid']??0);$key=isset($_GET['key'])&&is_string($_GET['key'])?sanitize_text_field(wp_unslash($_GET['key'])):'';if(!$pid||strlen($key)!==64||!ctype_xdigit($key))wp_die('Ongeldige agenda-link','Geen toegang',['response'=>403]);$hash=hash('sha256',$key);$saved=$wpdb->get_var($wpdb->prepare('SELECT token_hash FROM '.self::table('feeds').' WHERE person_id=%d',$pid));if(!$saved||!hash_equals($saved,$hash))wp_die('Ongeldige agenda-link','Geen toegang',['response'=>403]);$rows=$wpdb->get_results($wpdb->prepare('SELECT s.*,p.name,g.name group_name FROM '.Dares_Piket_Advanced::t('shifts').' s JOIN '.Dares_Piket_Advanced::t('people').' p ON p.id=s.person_id JOIN '.Dares_Piket_Advanced::t('groups').' g ON g.id=s.group_id WHERE s.person_id=%d AND s.end_at>%s ORDER BY start_at LIMIT 1000',$pid,wp_date('Y-m-d H:i:s',strtotime('-2 months'))));nocache_headers();header('Content-Type: text/calendar; charset=utf-8');header('Content-Disposition: inline; filename="dares-persoonlijk.ics"');header('X-Robots-Tag: noindex, nofollow');$host=preg_replace('/[^a-z0-9.-]/i','',wp_parse_url(home_url(),PHP_URL_HOST));echo "BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//DARES//Piketrooster v2//NL\r\nCALSCALE:GREGORIAN\r\nMETHOD:PUBLISH\r\nX-WR-CALNAME:DARES persoonlijk piket\r\n";foreach($rows as $r){$f=static function($v){return (new DateTimeImmutable($v,wp_timezone()))->setTimezone(new DateTimeZone('UTC'))->format('Ymd\THis\Z');};$summary=self::ical_escape('DARES Piket: '.$r->name.' ('.$r->group_name.')');echo "BEGIN:VEVENT\r\nUID:dares-piket-".(int)$r->id.'@'.$host."\r\nDTSTAMP:".gmdate('Ymd\THis\Z')."\r\nDTSTART:".$f($r->start_at)."\r\nDTEND:".$f($r->end_at)."\r\nSUMMARY:".$summary."\r\nEND:VEVENT\r\n";}$cancellations=$wpdb->get_results($wpdb->prepare('SELECT * FROM '.self::table('cancelled').' WHERE person_id=%d AND canceled_at > DATE_SUB(NOW(),INTERVAL 180 DAY) LIMIT 200',$pid));foreach($cancellations as $c){echo "BEGIN:VEVENT\r\nUID:dares-piket-".(int)$c->shift_id.'@'.$host."\r\nDTSTAMP:".gmdate('Ymd\THis\Z')."\r\nSTATUS:CANCELLED\r\nSEQUENCE:2\r\nSUMMARY:DARES Piket geannuleerd\r\nEND:VEVENT\r\n";}echo "END:VCALENDAR\r\n";exit;}
 static function ical_escape($s){return str_replace(["\\",';',',',"\r","\n"],['\\\\','\\;','\\,','','\\n'],$s);}
 static function audit(){self::sync_snapshot(false);$o=self::settings();global $wpdb;$now=Dares_Piketrooster::now();$limit=current_datetime()->modify('+'.(int)$o['deadline_hours'].' hours')->format('Y-m-d H:i:s');$rows=$wpdb->get_results($wpdb->prepare('SELECT s.*,p.name FROM '.Dares_Piket_Advanced::t('shifts').' s JOIN '.Dares_Piket_Advanced::t('people').' p ON p.id=s.person_id LEFT JOIN '.Dares_Piket_Advanced::t('confirm').' c ON c.shift_id=s.id WHERE s.start_at>%s AND s.start_at<=%s AND c.shift_id IS NULL LIMIT 200',$now,$limit));$to=sanitize_email($o['escalate_email']);if(!$to)return;foreach($rows as $r){$key='deadline-'.$r->id.'-'.$r->start_at;$seen=$wpdb->get_var($wpdb->prepare('SELECT id FROM '.self::table('events').' WHERE event_key=%s',$key));if($seen)continue;if(wp_mail($to,'DARES: piketbevestiging ontbreekt','Dienst #'.$r->id.' van '.$r->name.' begint '.$r->start_at.' en is nog niet bevestigd.'))self::log('deadline',$key,$r->name.' - '.$r->start_at);}}
 static function sync_snapshot($seed=false){global $wpdb;$rows=$wpdb->get_results('SELECT id,person_id,start_at,end_at FROM '.Dares_Piket_Advanced::t('shifts').' WHERE end_at > DATE_SUB(NOW(),INTERVAL 120 DAY) ORDER BY id DESC LIMIT 4000');$now=[];foreach($rows as $r)$now[(int)$r->id]=[(int)$r->person_id,$r->start_at,$r->end_at];$before=(array)get_option('dares_piket_v2_snapshot',[]);if(!$seed)foreach($before as $id=>$item){if(!isset($now[$id])&&isset($item[0]))$wpdb->replace(self::table('cancelled'),['shift_id'=>absint($id),'person_id'=>absint($item[0]),'canceled_at'=>Dares_Piketrooster::now()]);elseif(isset($now[$id])&&$now[$id][0]!=(int)$item[0])$wpdb->replace(self::table('cancelled'),['shift_id'=>absint($id),'person_id'=>absint($item[0]),'canceled_at'=>Dares_Piketrooster::now()]);}update_option('dares_piket_v2_snapshot',$now,false);}
 static function assets(){wp_register_style('dares-piket-v2',plugins_url('../assets/v2.css',__FILE__),[], '2.0.0');wp_enqueue_style('dares-piket-v2');}
 static function pwa_head(){/* PWA 2.1 renders the enhanced manifest. */}
 static function pwa_route(){if(isset($_GET['dares-piket-manifest'])){if(!self::settings()['pwa'])status_header(404);else{header('Content-Type: application/manifest+json; charset=utf-8');echo wp_json_encode(['name'=>'DARES Piketrooster','short_name'=>'DARES Piket','start_url'=>Dares_Piket_Advanced::portal_url(),'display'=>'standalone','theme_color'=>'#ffcc00','background_color'=>'#ffffff','icons'=>[['src'=>plugins_url('../assets/icon-192.png',__FILE__),'sizes'=>'192x192','type'=>'image/png'],['src'=>plugins_url('../assets/icon-512.png',__FILE__),'sizes'=>'512x512','type'=>'image/png']]]);}exit;}
 if(!isset($_GET['dares_piket_print'])||!current_user_can('manage_options'))return;echo '<!doctype html><html lang="nl"><head><meta charset="utf-8"><title>DARES jaarrooster</title><style>body{font:15px Arial;margin:35px}h1{color:#123a5a}.dares-v2-year>div{padding:9px;border-bottom:1px solid #ddd;display:flex;gap:20px}small{min-width:180px}button{margin-bottom:20px}@media print{button{display:none}}</style></head><body><button onclick="window.print()">Afdrukken / opslaan als PDF</button><h1>DARES Piketrooster</h1>'.self::year([]).'</body></html>';exit;}
}
